export function normalizeText(t){return String(t||"").toLowerCase()}export function getFamilyChildrenCount(t){return Number.isFinite(t.childrenCount)?t.childrenCount:Array.isArray(t.children)?t.children.length:0}export function familyMatchesSearch(t,e){if(!e)return!0;const i=normalizeText(e);return[t.id,t.email,t.familyId].map(normalizeText).join(" ").includes(i)}export function applyFamiliesFilters(t,e){return t.filter(t=>("all"===e.status||"active"===e.status&&!t.isBlocked||"blocked"===e.status&&t.isBlocked)&&familyMatchesSearch(t,e.search)).sort((t,i)=>{if("active"===e.sort){const e=t.last_activity?new Date(t.last_activity).getTime():0;return(i.last_activity?new Date(i.last_activity).getTime():0)-e}const a=t.created_at?new Date(t.created_at).getTime():0;return(i.created_at?new Date(i.created_at).getTime():0)-a})}